Definition sec_b1_mem (M : word -> option byte) (s stat sec msz lg r pab2 nch : Z) : word -> option byte :=
  Wn 8 (Wn 8 (Wn 8 (Wn 8 (Wn 8 (Wn 8 (Wn 8 (Wn 4 (Wn 8 (Wn 8 (Wn 8 (Wn 8 (Wn 8 (Wn 8 M
    (s - 104) 0x5e030) (s - 112) stat) (s - 120) sec) (s - 128) msz) (s - 136) lg) (s - 144) (4096 + r)) (s - 192) 50)
    (s - 200) 0x9494c) (s - 208) 131072) (s - 216) 0) (s - 224) (pab2 + 8 * nch)) (s - 232) 0) (s - 240) 0x1ef520) (s - 248) r.

(* [comment removed for export] *)
#[using="Type"] Lemma sec_b1_fn : forall regs (M rom : word -> option byte) (s sec stat lg nch pab2 r msz : Z),
  getr regs 2 = Z_to_bv 64 (s - 96) -> getr regs 8 = Z_to_bv 64 stat -> getr regs 9 = Z_to_bv 64 sec -> getr regs 10 = Z_to_bv 64 (4096 + r) ->
  getr regs 13 = Z_to_bv 64 nch -> getr regs 14 = Z_to_bv 64 nch -> getr regs 18 = Z_to_bv 64 msz -> getr regs 19 = Z_to_bv 64 lg -> getr regs 21 = Z_to_bv 64 r ->
  0x6b6000 <= s - 464 -> s < 2 ^ 47 -> 4096 <= r -> r < 2 ^ 47 -> 0 <= msz < 2 ^ 47 -> 0 <= stat < 2 ^ 64 -> 0 <= lg <= 63 ->
  0x10000 <= sec -> sec + 1024 < 0x6b6000 -> 0 <= nch < 2 ^ 20 -> 4096 <= pab2 -> pab2 + 8 * nch + 131072 < 2 ^ 47 -> (pab2 + 8 * nch) mod 4096 = 0 ->
  wrA M (s - 464) 464 ->
  cellA M (sec + 16) 8 pab2 -> cellA M 0x156d78 8 0x1ef520 -> cellA M 0x1ef520 8 4096 ->
  msteps ASEGS (mkst regs (0x5de34 : word) M rom)
    (mkst (regupd (regupd (regupd (regupd (regupd (regupd (regupd (regupd (regupd (regupd (regupd (regupd (regupd (regupd (regupd regs
             1 (Z_to_bv 64 0x94968)) 2 (Z_to_bv 64 (s - 192))) 8 (Z_to_bv 64 131072)) 9 (Z_to_bv 64 0)) 10 (Z_to_bv 64 (pab2 + 8 * nch))) 11 (Z_to_bv 64 131072)) 12 (Z_to_bv 64 3)) 13 (Z_to_bv 64 50))
             14 (Z_to_bv 64 18446744073709551615)) 15 (Z_to_bv 64 0)) 17 (Z_to_bv 64 222)) 18 (Z_to_bv 64 (pab2 + 8 * nch))) 19 (Z_to_bv 64 0)) 20 (Z_to_bv 64 0x1ef520)) 21 (Z_to_bv 64 r))
