  0x10000 <= sec -> sec + 1024 < 0x6b6000 -> 0x10000 <= stat -> stat + 64 < 0x6b6000 -> 0 <= nch < 2 ^ 20 -> 0 <= nres < 2 ^ 40 -> 0 <= lg <= 63 -> 0x10000 <= F -> F + 512 < 0x6b6000 ->
