#[using="Type"] Theorem art_sec_postB1_run : forall regs (M1 rom : word -> option byte)
    (s sec stat msz n r F tp key tsd ctx t C D nch pab2 : Z),
  getr regs 1 = Z_to_bv 64 0x944f8 -> getr regs 2 = Z_to_bv 64 (s - 144) -> getr regs 4 = Z_to_bv 64 tp -> getr regs 10 = Z_to_bv 64 r -> getr regs 19 = Z_to_bv 64 n ->
  getr regs 21 = Z_to_bv 64 8 -> getr regs 24 = Z_to_bv 64 7 ->
  (* [comment removed for export] *)
  kHighMemBeg <= s - 464 -> s < 2 ^ 47 -> 0 <= n -> n mod 8 = 0 -> 2 ^ 12 <= msz -> msz mod 4096 = 0 -> n + 4096 <= msz ->
  4096 <= r -> r mod 4096 = 0 -> r + msz < 2 ^ 47 -> 0x6b6000 <= r -> appmem r msz -> apart r msz (s - 464) 464 ->
  0x10000 <= sec -> sec + 1024 < 0x6b6000 -> sec + 624 <= stat -> stat + 64 < 0x6b6000 -> (sec + 616) mod 4 = 0 -> stat mod 8 = 0 ->
  0x10000 <= F -> F + 512 < 0x6b6000 ->
  ((4096 <= t /\ t + 4096 <= 0x10000) \/ 0x6b6000 <= t) -> t + 4096 < 2 ^ 47 -> appmem t 4096 -> apart (t + 2872) 16 r 32 -> apart (t + 2872) 16 (s - 464) 464 -> apart (t + 2872) 16 (ctx + 152) 8 ->
  0 <= C -> C < 2 ^ 64 -> 0 <= D -> D < 2 ^ 64 ->
  (* [comment removed for export] *)
  appmem ctx 4096 -> apart (ctx + 152) 8 r 32 -> apart (ctx + 152) 8 (s - 464) 464 -> 4096 <= tp - 88 -> tp < 0x6b6000 -> 4096 <= tsd -> tsd + 8 * key + 8 <= 0x6b6000 ->
  (* [comment removed for export] *)
  wrA M1 (s - 464) 464 -> wrA M1 r 32 -> wrA M1 (SB + r / 8) (msz / 8) -> wrA M1 (t + 2872) 16 -> wrA M1 sec 624 ->
  cellA M1 (s - 104) 8 0x5dc90 -> cellA M1 (s - 112) 8 stat -> cellA M1 (s - 120) 8 sec -> cellA M1 (s - 128) 8 msz ->
  cellA M1 sec 8 4096 -> cellA M1 0x156d88 8 F -> cellA M1 (F + 144) 8 0 -> art_layout M1 -> art_tsd M1 tp key tsd ctx t ->
  cellA M1 (t + 2872) 8 C -> cellA M1 (t + 2880) 8 D -> cellA M1 (sec + 616) 4 0 -> cellA M1 (sec + 56) 8 nch -> cellA M1 (sec + 48) 8 nch ->
  (* [comment removed for export] *)
  0 <= nch < 2 ^ 20 -> 0x157840 <= sec -> sec + 1024 <= 0x1ef520 -> cellA M1 (sec + 16) 8 pab2 -> cellA M1 0x156d78 8 0x1ef520 -> cellA M1 0x1ef520 8 4096 -> 4096 <= pab2 -> pab2 + 8 * nch + 131072 < 2 ^ 47 -> (pab2 + 8 * nch) mod 4096 = 0 ->
  exists regs', msteps ASEGS (mkst regs (0x92bac : word) M1 rom)
     (mkst regs' (0x92ba8 : word) (sec_b1_mem (sec_hm M1 s stat sec msz n r t C D) s stat sec msz (63 - Z.log2 msz) r pab2 nch) rom)
  /\ getr regs' 17 = Z_to_bv 64 222 /\ getr regs' 10 = Z_to_bv 64 (pab2 + 8 * nch) /\ getr regs' 11 = Z_to_bv 64 131072 /\ getr regs' 12 = Z_to_bv 64 3
  /\ getr regs' 13 = Z_to_bv 64 50 /\ getr regs' 14 = Z_to_bv 64 18446744073709551615 /\ getr regs' 15 = Z_to_bv 64 0
  /\ getr regs' 1 = Z_to_bv 64 0x94968 /\ getr regs' 2 = Z_to_bv 64 (s - 192) /\ getr regs' 8 = Z_to_bv 64 131072 /\ getr regs' 9 = Z_to_bv 64 0
  /\ getr regs' 18 = Z_to_bv 64 (pab2 + 8 * nch) /\ getr regs' 19 = Z_to_bv 64 0 /\ getr regs' 20 = Z_to_bv 64 0x1ef520 /\ getr regs' 21 = Z_to_bv 64 r /\ getr regs' 4 = Z_to_bv 64 tp
